def digest(path: pathlib.Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def required_artifacts(destination: pathlib.Path, run_id: str) -> frozenset[str]:
    receipt = destination / "dispatch-ultra-light.json"
    if not receipt.is_file():
        return CORE_ARTIFACTS
    data = json.loads(receipt.read_text())
    if data.get("run_id") != run_id or data.get("run_profile") != "ultra-light":
        raise ValueError("ultra-light dispatch receipt has the wrong run identity")
    return ULTRA_LIGHT_ARTIFACTS


def main(run_id: str, destination: pathlib.Path) -> int:
    destination.mkdir(parents=True, exist_ok=True)
    errors = []
    monitor = EventLog(run_id, destination)
    monitor_thread = threading.Thread(target=monitor.follow, name="fabro-event-monitor", daemon=True)
    resource_thread = threading.Thread(target=monitor.sample_resources, name="docker-resource-monitor", daemon=True)
    monitor_thread.start()
    resource_thread.start()
    try:
        wait = command("wait", "--json", "--timeout", "30000", run_id, timeout=30100)
    finally:
        monitor.stop()
        monitor_thread.join(timeout=10)
        resource_thread.join(timeout=12)
    if monitor_thread.is_alive():
        errors.append("Fabro event monitor did not stop")
    if monitor.error:
        errors.append("Fabro event monitor failed: " + monitor.error)
    if resource_thread.is_alive():
        errors.append("Docker resource monitor did not stop")

    dump_path = destination / "full-dump"
    result = command("dump", "--json", "--output", str(dump_path), run_id)
    if result.returncode:
        errors.append("Fabro dump failed: " + result.stderr.strip()[:500])

    artifact_path = destination / "artifacts"
    artifact_path.mkdir(exist_ok=True)
    result = command("artifact", "cp", "--json", "--tree", run_id, str(artifact_path))
    artifact_error = result.stderr.strip() if result.returncode else ""

    run_path = dump_path / "run.json"
    run = json.loads(run_path.read_text()) if run_path.is_file() else {}
    status = run.get("status", {})
    runtime = run.get("sandbox", {}).get("instance", {}).get("runtime", {})
    container_id = runtime.get("id")
    capture_path = destination / "worker-capture"
    capture_complete = False
    if status.get("kind") == "succeeded":
        if not container_id:
            errors.append("Fabro terminal dump has no worker container identity")
        else:
            capture_path.mkdir(exist_ok=True)
            capture = subprocess.run(["docker", "cp", f"{container_id}:/workspace/.",
                                      str(capture_path)], text=True, capture_output=True,
                                     timeout=600, check=False)
            if capture.returncode:
                errors.append("stopped worker capture failed: " + capture.stderr.strip()[:500])
            else:
                manifest_path = capture_path / "reports/review-index.json"
                if not manifest_path.is_file():
                    errors.append("worker capture lacks reports/review-index.json")
                else:
                    try:
                        worker_manifest = json.loads(manifest_path.read_text())
                        expected = worker_manifest.get("artifacts", {})
                        if not isinstance(expected, dict) or not expected:
                            errors.append("worker review manifest has no artifact hashes")
                        else:
                            missing = sorted(required_artifacts(destination, run_id) - expected.keys())
                            if missing:
                                errors.append("worker review manifest omits required artifacts: " + ", ".join(missing))
                            for name, expected_sha in expected.items():
                                relative = pathlib.PurePosixPath(name)
                                if (relative.is_absolute() or ".." in relative.parts or
                                        not re.fullmatch(r"[0-9a-f]{64}", str(expected_sha))):
                                    errors.append("worker manifest contains an unsafe path or hash")
                                    break
                                artifact = capture_path.joinpath(*relative.parts)
                                if not artifact.is_file() or digest(artifact) != expected_sha:
                                    errors.append("worker artifact missing or hash mismatch: " + name)
                                    if len(errors) >= 20:
                                        errors.append("additional worker artifact omissions suppressed")
                                        break
                            capture_complete = not errors
                    except (OSError, ValueError, json.JSONDecodeError) as exc:
                        errors.append("worker review manifest is unreadable: " + str(exc)[:300])
    conclusion = run.get("conclusion") or {}
    if wait.returncode and not run:
        errors.append("Fabro wait failed: " + wait.stderr.strip()[:500])
    if artifact_error and not capture_complete and not (
            status.get("kind") == "failed" and "No artifacts found" in artifact_error):
        errors.append("Fabro artifact export failed: " + artifact_error[:500])
    if not monitor.catch_up():
        errors.append("Fabro event catch-up failed")
    terminal_status = status.get("kind", "unknown")
    if status.get("reason"):
        terminal_status += "/" + status["reason"]
    monitor.close(terminal_status)
    files = {str(path.relative_to(destination)): digest(path)
             for path in sorted(destination.rglob("*")) if path.is_file()
             and path.name != "morning-review-index.json"}
    candidate_files = {}
    worker_manifest_path = capture_path / "reports/review-index.json"
    if worker_manifest_path.is_file():
        try:
            candidate_files = json.loads(worker_manifest_path.read_text()).get("artifacts", {})
        except (OSError, ValueError, json.JSONDecodeError):
            candidate_files = {}
    if status.get("kind") == "succeeded" and not candidate_files:
        errors.append("terminal candidate identity cannot be established without its worker manifest")
    candidate_identity = hashlib.sha256(json.dumps(candidate_files, sort_keys=True).encode()).hexdigest() \
        if candidate_files else None
    index = {
        "schema_version": 1,
        "run_id": run_id,
        "status": status,
        "candidate_identity_sha256": candidate_identity,
        "base_commit": BASE,
        "scope": "SANITIZED standalone X-COM T025 candidate: time authority, one-time permit, bounded validation sessions",
        "review_status": "manual Codex review pending",
        "requirements_design_code_tests_trace": [name for name in candidate_files if name.endswith((
            "requirements.md", "design.md", "verification-plan.md", "validation_session.hpp",
            "validation_session.cpp", "validation_session_tests.cpp", "trace.md", "validation.md",
            "internal-review.md", "review-index.json"))],
        "test_validation_result": "See worker review-index.json and full-dump stage outputs; no protected predecessor integration is claimed",
        "known_issues": [conclusion.get("failure")] if conclusion.get("failure") else [],
        "remaining_decisions": ["Protected predecessor integration, full regression, and external acceptance remain open"],
        "deepseek_usage": conclusion.get("usage"),
        "resource_sampling": monitor.status.get("resources"),
        "deepseek_cost": "Fabro catalog estimate only, if present in usage; provider billing not confirmed",
        "collection_errors": errors,
        "full_evidence_sha256": files,
    }
    (destination / "morning-review-index.json").write_text(
        json.dumps(index, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    return 0 if run and not errors else 1


if __name__ == "__main__":
    if len(sys.argv) != 3:
        raise SystemExit("usage: collect_terminal.py RUN_ID DESTINATION")
    raise SystemExit(main(sys.argv[1], pathlib.Path(sys.argv[2])))

