/// R6 re-declaration: an observation captured from one clock declaration must never seed the
/// retained baseline of a replacement declaration of the same domain. The re-declaring thread is
/// released only after the transition's non-mutating peek has read the original declaration, so
/// the replacement is guaranteed to be concurrent with (or to precede) the deferred commit. The
/// assertion is schedule-independent: whether the commit wins or loses the race, the replacement
/// declaration ends with no retained baseline.
TEST(SessionManagerUnit, BUG_R6_ConcurrentRedeclaration) {
  v::SessionManager manager(scoped_config(1));
  const v::ControllerId controller = controller_id(1);
  ASSERT_EQ(manager.register_controller(controller, "ctrl"), v::Result::Ok);
  std::atomic<v::Timestamp> source{1500};
  std::atomic<bool> peeked{false};
  ASSERT_EQ(manager.time_authority().declare_clock(
                kMono,
                [&source, &peeked]() -> std::optional<v::Timestamp> {
                  peeked.store(true, std::memory_order_release);
                  return source.load();
                },
                v::ClockKind::Monotonic, 0, 1000000),
            v::Result::Ok);
  const v::Permit permit = make_valid_permit();
  v::SessionHandle handle{};
  ASSERT_EQ(consume_permit(manager, controller, permit, handle), v::Result::Ok);

  std::atomic<bool> redeclared{false};
  std::thread redeclarer([&manager, &source, &peeked, &redeclared]() {
    while (!peeked.load(std::memory_order_acquire)) {
      std::this_thread::yield();
    }
    const v::Result result = manager.time_authority().declare_clock(
        kMono, [&source]() -> std::optional<v::Timestamp> { return source.load(); },
        v::ClockKind::Monotonic, 0, 1000000);
    redeclared.store(result == v::Result::Ok, std::memory_order_release);
  });

  v::Diagnostic diagnostic;
  ASSERT_EQ(manager.transition(handle, v::Action::Arm, kMono, 1500, diagnostic), v::Result::Ok);
  redeclarer.join();
  ASSERT_TRUE(redeclared.load(std::memory_order_acquire));
  // The replacement declaration starts empty and must not inherit the pre-declaration reading.
  EXPECT_FALSE(manager.time_authority().baseline(kMono).has_value());
  // It still serves ordinary public reads, and regression is measured against its own baseline.
  source.store(1400);
  v::Timestamp out = 0;
  ASSERT_EQ(manager.time_authority().now(kMono, out), v::Result::Ok);
  EXPECT_EQ(out, 1400);
  ASSERT_EQ(manager.time_authority().baseline(kMono).value(), 1400);
  source.store(1300);
  EXPECT_EQ(manager.time_authority().now(kMono, out), v::Result::ClockRegression);
}

/// R6 mapped re-declaration: for a mapped transition the destination baseline is committed to
/// the destination-domain host reading used by the tolerance check. Re-declaring the destination
/// domain while the transition is in flight must not attribute that reading to the replacement.
/// The source declaration is untouched, so only its baseline is retained.
TEST(SessionManagerUnit, BUG_R6_MappedRedeclaration) {
  v::SessionManager manager(scoped_config(1));
  const v::ControllerId controller = controller_id(1);
  ASSERT_EQ(manager.register_controller(controller, "ctrl"), v::Result::Ok);
  std::atomic<v::Timestamp> source{1500};
  std::atomic<v::Timestamp> destination{1500};
  std::atomic<bool> destination_peeked{false};
  ASSERT_EQ(manager.time_authority().declare_clock(
                kWall, [&source]() -> std::optional<v::Timestamp> { return source.load(); },
                v::ClockKind::Monotonic, 0, 1000000),
            v::Result::Ok);
  ASSERT_EQ(manager.time_authority().declare_clock(
                kMono,
                [&destination, &destination_peeked]() -> std::optional<v::Timestamp> {
                  destination_peeked.store(true, std::memory_order_release);
                  return destination.load();
                },
                v::ClockKind::Monotonic, 0, 1000000),
            v::Result::Ok);
  ASSERT_EQ(manager.time_authority().declare_mapping(kWall, kMono, 0, 10), v::Result::Ok);
  const v::Permit permit = make_valid_permit();
  v::SessionHandle handle{};
  ASSERT_EQ(consume_permit(manager, controller, permit, handle), v::Result::Ok);

  std::atomic<bool> redeclared{false};
  std::thread redeclarer([&manager, &destination, &destination_peeked, &redeclared]() {
    while (!destination_peeked.load(std::memory_order_acquire)) {
      std::this_thread::yield();
    }
    const v::Result result = manager.time_authority().declare_clock(
        kMono,
        [&destination]() -> std::optional<v::Timestamp> { return destination.load(); },
        v::ClockKind::Monotonic, 0, 1000000);
    redeclared.store(result == v::Result::Ok, std::memory_order_release);
  });

  v::Diagnostic diagnostic;
  ASSERT_EQ(manager.transition(handle, v::Action::Arm, kWall, 1500, diagnostic), v::Result::Ok);
  redeclarer.join();
  ASSERT_TRUE(redeclared.load(std::memory_order_acquire));
  // The untouched source declaration retains the reading it produced.
  ASSERT_TRUE(manager.time_authority().baseline(kWall).has_value());
  EXPECT_EQ(manager.time_authority().baseline(kWall).value(), 1500);
  // The replacement destination declaration must not inherit the mapped destination reading.
  EXPECT_FALSE(manager.time_authority().baseline(kMono).has_value());
  destination.store(1400);
  v::Timestamp out = 0;
  ASSERT_EQ(manager.time_authority().now(kMono, out), v::Result::Ok);
  EXPECT_EQ(out, 1400);
}

