 159 | /// \brief Returns the locator of the first field where the context differs from the permit.
 160 | /// \param permit Immutable permit.
 161 | /// \param context Asserted runtime envelope.
 162 | /// \return The first mismatching field locator, or `std::nullopt` when all fields match.
 163 | /// \unitspec{T025-U-PERMIT}
 164 | [[nodiscard]] std::optional<FieldLocator> first_mismatch(const Permit &permit,
 165 |                                                          const SessionContext &context) {
 166 |   if (permit.session_id() != context.session_id) {
 167 |     return FieldLocator::SessionId;
 168 |   }
 169 |   if (permit.plan_digest() != context.plan_digest) {
 170 |     return FieldLocator::PlanDigest;
 171 |   }
 172 |   if (permit.scenario() != context.scenario) {
 173 |     return FieldLocator::Scenario;
 174 |   }
 175 |   if (permit.deployment() != context.deployment) {
 176 |     return FieldLocator::Deployment;
 177 |   }
 178 |   if (permit.environment() != context.environment) {
 179 |     return FieldLocator::Environment;
 180 |   }
 181 |   if (permit.tool() != context.tool) {
 182 |     return FieldLocator::Tool;
 183 |   }
 184 |   if (permit.interface_name() != context.interface_name) {
 185 |     return FieldLocator::Interface;
 186 |   }
 187 |   if (permit.target() != context.target) {
 188 |     return FieldLocator::Target;
 189 |   }
 190 |   if (permit.nonce() != context.nonce) {
 191 |     return FieldLocator::Nonce;
 192 |   }
 193 |   if (!same_action_set(permit.allowed_actions(), context.allowed_actions)) {
 194 |     return FieldLocator::AllowedActions;
 195 |   }
 196 |   if (permit.validity_domain() != context.validity_domain ||
 197 |       permit.valid_from() != context.valid_from || permit.valid_until() != context.valid_until) {
 198 |     return FieldLocator::Validity;
 199 |   }
 200 |   if (!same_quota_set(permit.quotas(), context.quotas)) {
 201 |     return FieldLocator::Quota;
 202 |   }
 203 |   return std::nullopt;
 204 | }
