 208 | Diagnostic Diagnostic::from_first(std::initializer_list<Result> applicable,
 209 |                                   std::optional<std::uint32_t> locator) noexcept {
 210 |   Diagnostic diagnostic;
 211 |   diagnostic.size_ = 1;
 212 |   Result best = Result::Ok;
 213 |   bool assigned = false;
 214 |   for (const Result candidate : applicable) {
 215 |     if (!assigned || precedence_rank(candidate) < precedence_rank(best)) {
 216 |       best = candidate;
 217 |       assigned = true;
 218 |     }
 219 |   }
 220 |   diagnostic.codes_[0] = best;
 221 |   diagnostic.locator_ = locator;
 222 |   return diagnostic;
 223 | }
 224 | 
 225 | Diagnostic Diagnostic::accumulate(std::initializer_list<Result> codes,
 226 |                                   std::optional<std::uint32_t> locator) noexcept {
 227 |   Diagnostic diagnostic;
 228 |   diagnostic.locator_ = locator;
 229 |   for (const Result code : codes) {
 230 |     if (diagnostic.size_ >= capacity) {
 231 |       break;
 232 |     }
 233 |     diagnostic.codes_[diagnostic.size_] = code;
 234 |     ++diagnostic.size_;
 235 |   }
 236 |   std::sort(
 237 |       diagnostic.codes_.begin(),
 238 |       diagnostic.codes_.begin() + static_cast<std::ptrdiff_t>(diagnostic.size_),
 239 |       [](Result left, Result right) { return precedence_rank(left) < precedence_rank(right); });
 240 |   return diagnostic;
 241 | }
