 368 | Result PermitBuilder::build(Permit &out) const {
 369 |   last_locator_.reset();
 370 |   const auto fail = [this](FieldLocator locator) -> Result {
 371 |     last_locator_ = locator;
 372 |     return Result::InvalidPermit;
 373 |   };
 374 |   if (is_zero_bytes(session_id_)) {
 375 |     return fail(FieldLocator::SessionId);
 376 |   }
 377 |   if (is_zero_bytes(plan_digest_)) {
 378 |     return fail(FieldLocator::PlanDigest);
 379 |   }
 380 |   if (!Tag::is_valid(scenario_)) {
 381 |     return fail(FieldLocator::Scenario);
 382 |   }
 383 |   if (!Tag::is_valid(deployment_)) {
 384 |     return fail(FieldLocator::Deployment);
 385 |   }
 386 |   if (!Tag::is_valid(environment_)) {
 387 |     return fail(FieldLocator::Environment);
 388 |   }
 389 |   if (!Tag::is_valid(tool_)) {
 390 |     return fail(FieldLocator::Tool);
 391 |   }
 392 |   if (!Tag::is_valid(interface_name_)) {
 393 |     return fail(FieldLocator::Interface);
 394 |   }
 395 |   if (!Tag::is_valid(target_)) {
 396 |     return fail(FieldLocator::Target);
 397 |   }
 398 |   if (allowed_actions_.empty() || allowed_actions_.size() > max_allowed_actions) {
 399 |     return fail(FieldLocator::AllowedActions);
 400 |   }
 401 |   for (const ActionMask mask : allowed_actions_) {
 402 |     if (!is_single_action(mask) || !is_defined_action(mask)) {
 403 |       return fail(FieldLocator::AllowedActions);
 404 |     }
 405 |   }
 406 |   if (validity_domain_ == kInvalidClockDomain || valid_from_ > valid_until_) {
 407 |     return fail(FieldLocator::Validity);
 408 |   }
 409 |   if (quotas_.size() > max_quotas) {
 410 |     return fail(FieldLocator::Quota);
 411 |   }
 412 |   for (const Quota &quota : quotas_) {
 413 |     if (!is_known_quota_kind(quota.kind) || quota.limit == 0U) {
 414 |       return fail(FieldLocator::Quota);
 415 |     }
 416 |   }
 417 |   Permit built;
 418 |   built.session_id_ = session_id_;
 419 |   built.plan_digest_ = plan_digest_;
 420 |   built.scenario_ = scenario_;
 421 |   built.deployment_ = deployment_;
 422 |   built.environment_ = environment_;
 423 |   built.tool_ = tool_;
 424 |   built.interface_name_ = interface_name_;
 425 |   built.target_ = target_;
 426 |   built.nonce_ = nonce_;
 427 |   built.validity_domain_ = validity_domain_;
 428 |   built.valid_from_ = valid_from_;
 429 |   built.valid_until_ = valid_until_;
 430 |   built.allowed_actions_ = allowed_actions_;
 431 |   built.quotas_ = quotas_;
 432 |   built.permit_id_ = canonical_digest(permit_envelope_bytes(built));
 433 |   out = built;
 434 |   return Result::Ok;
 435 | }
