 470 | Result TimeAuthority::declare_clock(ClockDomainId id, ClockSource source, ClockKind kind,
 471 |                                     Timestamp min_value, Timestamp max_value) {
 472 |   std::lock_guard<std::mutex> lock(mutex_);
 473 |   if (id == kInvalidClockDomain || min_value > max_value) {
 474 |     return Result::UnknownClock;
 475 |   }
 476 |   ClockEntry *target = find_clock_locked(id);
 477 |   if (target == nullptr) {
 478 |     for (ClockEntry &entry : clocks_) {
 479 |       if (!entry.occupied) {
 480 |         target = &entry;
 481 |         break;
 482 |       }
 483 |     }
 484 |   }
 485 |   if (target == nullptr) {
 486 |     return Result::CapacityExhausted;
 487 |   }
 488 |   target->id = id;
 489 |   target->kind = kind;
 490 |   target->min_value = min_value;
 491 |   target->max_value = max_value;
 492 |   target->source = std::move(source);
 493 |   target->baseline.reset();
 494 |   // Every successful (re-)declaration receives a fresh generation, so a deferred commit of an
 495 |   // observation captured under a previous declaration can never be attributed to this one.
 496 |   target->declaration = ++declaration_counter_;
 497 |   target->occupied = true;
 498 |   return Result::Ok;
 499 | }
