 501 | Result TimeAuthority::declare_mapping(ClockDomainId src, ClockDomainId dst, SignedOffset offset,
 502 |                                       Tolerance tolerance) {
 503 |   std::lock_guard<std::mutex> lock(mutex_);
 504 |   if (src == kInvalidClockDomain || dst == kInvalidClockDomain) {
 505 |     return Result::UnknownClock;
 506 |   }
 507 |   if (find_clock_locked(src) == nullptr || find_clock_locked(dst) == nullptr) {
 508 |     return Result::UnknownClock;
 509 |   }
 510 |   MappingEntry *target = nullptr;
 511 |   for (MappingEntry &entry : mappings_) {
 512 |     if (entry.occupied && entry.src == src && entry.dst == dst) {
 513 |       target = &entry;
 514 |       break;
 515 |     }
 516 |   }
 517 |   if (target == nullptr) {
 518 |     for (MappingEntry &entry : mappings_) {
 519 |       if (!entry.occupied) {
 520 |         target = &entry;
 521 |         break;
 522 |       }
 523 |     }
 524 |   }
 525 |   if (target == nullptr) {
 526 |     return Result::CapacityExhausted;
 527 |   }
 528 |   target->src = src;
 529 |   target->dst = dst;
 530 |   target->offset = offset;
 531 |   target->tolerance = tolerance;
 532 |   target->occupied = true;
 533 |   return Result::Ok;
