 536 | Result TimeAuthority::read_clock_locked(ClockEntry &entry, Timestamp &out, bool commit_baseline) {
 537 |   if (!entry.source) {
 538 |     return Result::ClockSourceFailure;
 539 |   }
 540 |   const std::optional<Timestamp> reading = entry.source();
 541 |   if (!reading.has_value()) {
 542 |     return Result::ClockSourceFailure;
 543 |   }
 544 |   const Timestamp value = reading.value();
 545 |   if (value < entry.min_value || value > entry.max_value) {
 546 |     return Result::ClockOutOfBounds;
 547 |   }
 548 |   if (entry.kind == ClockKind::Monotonic && entry.baseline.has_value() &&
 549 |       value < entry.baseline.value()) {
 550 |     return Result::ClockRegression;
 551 |   }
 552 |   if (commit_baseline) {
 553 |     entry.baseline = value;
 554 |   }
 555 |   out = value;
 556 |   return Result::Ok;
 557 | }
