 559 | Result TimeAuthority::now_impl(ClockDomainId id, Timestamp &out, bool commit_baseline,
 560 |                                std::uint64_t *declaration) {
 561 |   std::lock_guard<std::mutex> lock(mutex_);
 562 |   ClockEntry *entry = find_clock_locked(id);
 563 |   if (entry == nullptr) {
 564 |     return Result::UnknownClock;
 565 |   }
 566 |   const Result result = read_clock_locked(*entry, out, commit_baseline);
 567 |   if (result == Result::Ok && declaration != nullptr) {
 568 |     *declaration = entry->declaration;
 569 |   }
 570 |   return result;
 571 | }
