 577 | Result TimeAuthority::convert_impl(ClockDomainId src, ClockDomainId dst, Timestamp value,
 578 |                                    Timestamp &out, bool commit_baseline,
 579 |                                    Timestamp *destination_reading,
 580 |                                    std::uint64_t *destination_declaration) {
 581 |   std::lock_guard<std::mutex> lock(mutex_);
 582 |   if (find_clock_locked(src) == nullptr) {
 583 |     return Result::UnknownClock;
 584 |   }
 585 |   const MappingEntry *mapping = find_mapping_locked(src, dst);
 586 |   if (mapping == nullptr) {
 587 |     return Result::MissingMapping;
 588 |   }
 589 |   ClockEntry *destination = find_clock_locked(dst);
 590 |   if (destination == nullptr) {
 591 |     return Result::UnknownClock;
 592 |   }
 593 |   Timestamp candidate = 0;
 594 |   if (__builtin_add_overflow(value, mapping->offset, &candidate)) {
 595 |     return Result::ClockOverflow;
 596 |   }
 597 |   if (candidate < destination->min_value || candidate > destination->max_value) {
 598 |     return Result::ClockOutOfBounds;
 599 |   }
 600 |   Timestamp destination_now = 0;
 601 |   const Result read = read_clock_locked(*destination, destination_now, /*commit_baseline=*/false);
 602 |   if (read != Result::Ok) {
 603 |     return read;
 604 |   }
 605 |   if (destination_reading != nullptr) {
 606 |     *destination_reading = destination_now;
 607 |   }
 608 |   if (destination_declaration != nullptr) {
 609 |     *destination_declaration = destination->declaration;
 610 |   }
 611 |   const std::uint64_t distance = unsigned_distance(candidate, destination_now);
 612 |   if (distance > mapping->tolerance) {
 613 |     return Result::ToleranceExceeded;
 614 |   }
 615 |   if (commit_baseline) {
 616 |     destination->baseline = destination_now;
 617 |   }
 618 |   out = candidate;
 619 |   return Result::Ok;
 620 | }
