 622 | Result TimeAuthority::convert(ClockDomainId src, ClockDomainId dst, Timestamp value,
 623 |                               Timestamp &out) {
 624 |   return convert_impl(src, dst, value, out, /*commit_baseline=*/true);
 625 | }
