 627 | void TimeAuthority::advance_baseline(ClockDomainId id, Timestamp reading,
 628 |                                      std::uint64_t declaration) {
 629 |   std::lock_guard<std::mutex> lock(mutex_);
 630 |   ClockEntry *entry = find_clock_locked(id);
 631 |   if (entry == nullptr || entry->declaration != declaration) {
 632 |     // Undeclared, or re-declared after the observation was captured: the reading belongs to a
 633 |     // different clock declaration and must never seed this one's retained baseline.
 634 |     return;
 635 |   }
 636 |   if (!entry->baseline.has_value() || reading >= entry->baseline.value()) {
 637 |     entry->baseline = reading;
 638 |   }
 639 | }
