 682 | ValidationSession::ValidationSession(const PermitId &permit_id, const SessionId &session_id,
 683 |                                      const ControllerId &controller, Generation generation,
 684 |                                      const std::vector<Quota> &quotas, LifecycleState initial_state)
 685 |     : state_(initial_state), permit_id_(permit_id), session_id_(session_id),
 686 |       controller_(controller), generation_(generation) {
 687 |   for (const Quota &quota : quotas) {
 688 |     const std::size_t index = quota_index(quota.kind);
 689 |     if (index < kQuotaKindCount && quota.limit != 0U && quotas_[index] == 0U) {
 690 |       quotas_[index] = quota.limit;
 691 |     }
 692 |   }
 693 | }
