 695 | Result ValidationSession::apply(Action action, Timestamp now) noexcept {
 696 |   static_cast<void>(now);
 697 |   const ActionMask mask = to_mask(action);
 698 |   if (!is_single_action(mask) || !is_defined_action(mask)) {
 699 |     return Result::UndefinedAction;
 700 |   }
 701 |   const TransitionOutcome outcome = transition_outcome(state_, action);
 702 |   if (outcome == TransitionOutcome::InvalidTransition) {
 703 |     return Result::InvalidTransition;
 704 |   }
 705 |   if (outcome == TransitionOutcome::TerminalState) {
 706 |     return Result::TerminalState;
 707 |   }
 708 |   if (quotas_[quota_index(QuotaKind::Operations)] == 0U) {
 709 |     return Result::QuotaExhausted;
 710 |   }
 711 |   if (outcome == TransitionOutcome::AlreadyApplied) {
 712 |     return Result::AlreadyApplied;
 713 |   }
 714 |   state_ = successor_state(state_, action);
 715 |   --quotas_[quota_index(QuotaKind::Operations)];
 716 |   return Result::Ok;
 717 | }
