 930 | /**
 931 |  * \brief Explicit time authority owning declared domains and directed mappings.
 932 |  *
 933 |  * The authority is non-copyable and non-movable: moving would silently invalidate the
 934 |  * injected host sources and regression baselines. Construct it with capacity bounds and
 935 |  * destroy it before any thread that used it exits. Every method is internally synchronized
 936 |  * by one mutex, so concurrent `now`/`convert` calls serialize into a deterministic total
 937 |  * order. No code path compares a raw timestamp from one domain with a raw timestamp from
 938 |  * another; conversion requires a declared directed mapping. Every declaration carries a
 939 |  * monotonic declaration generation, and a deferred commit is accepted only while the addressed
 940 |  * domain still carries the generation that produced the observation, so a concurrent
 941 |  * re-declaration can never attribute an old reading to its replacement.
 942 |  * \unitspec{T025-U-TIME}
 943 |  */
 944 | class TimeAuthority {
 945 | public:
 946 |   /// \brief Constructs an authority with bounded domain and mapping tables.
 947 |   /// \param max_domains Maximum number of declared clock domains.
 948 |   /// \param max_mappings Maximum number of directed mappings.
 949 |   /// \unitspec{T025-U-TIME}
 950 |   TimeAuthority(std::size_t max_domains, std::size_t max_mappings);
 951 |   /// \brief Destructor.
 952 |   /// \unitspec{T025-U-TIME}
 953 |   ~TimeAuthority() = default;
 954 | 
 955 |   /// \brief Copy construction is deleted; the authority is non-copyable.
 956 |   /// \unitspec{T025-U-TIME}
 957 |   TimeAuthority(const TimeAuthority &) = delete;
 958 |   /// \brief Copy assignment is deleted; the authority is non-copyable.
 959 |   /// \unitspec{T025-U-TIME}
 960 |   TimeAuthority &operator=(const TimeAuthority &) = delete;
 961 |   /// \brief Move construction is deleted; the authority is non-movable.
 962 |   /// \unitspec{T025-U-TIME}
 963 |   TimeAuthority(TimeAuthority &&) = delete;
 964 |   /// \brief Move assignment is deleted; the authority is non-movable.
 965 |   /// \unitspec{T025-U-TIME}
 966 |   TimeAuthority &operator=(TimeAuthority &&) = delete;
 967 | 
 968 |   /// \brief Declares or replaces a clock domain.
 969 |   /// \param id Domain token; `0` is reserved invalid.
 970 |   /// \param source Host-injected reading source, moved into the authority.
 971 |   /// \param kind Monotonic or wall-clock semantics.
 972 |   /// \param min_value Inclusive lower bound.
 973 |   /// \param max_value Inclusive upper bound.
 974 |   /// \return `Result::Ok`; `Result::CapacityExhausted` when the domain table is full and
 975 |   ///         `id` is new; `Result::UnknownClock` when `id == 0` or the bounds are inverted.
 976 |   /// \unitspec{T025-U-TIME}
 977 |   [[nodiscard]] Result declare_clock(ClockDomainId id, ClockSource source, ClockKind kind,
 978 |                                      Timestamp min_value, Timestamp max_value);
 979 | 
 980 |   /// \brief Declares or replaces a directed source-to-destination mapping.
 981 |   /// \param src Source domain; must already be declared.
 982 |   /// \param dst Destination domain; must already be declared.
 983 |   /// \param offset Signed offset added to the source value.
 984 |   /// \param tolerance Maximum admissible divergence from the destination reading.
 985 |   /// \return `Result::Ok`; `Result::UnknownClock` when either domain is undeclared;
 986 |   ///         `Result::CapacityExhausted` when the mapping table is full.
 987 |   /// \unitspec{T025-U-TIME}
 988 |   [[nodiscard]] Result declare_mapping(ClockDomainId src, ClockDomainId dst, SignedOffset offset,
 989 |                                        Tolerance tolerance);
 990 | 
 991 |   /// \brief Reads the bounded current time of a domain.
 992 |   /// \param id Declared domain token.
 993 |   /// \param out Receives the reading only on `Result::Ok`.
 994 |   /// \return `Result::Ok`; `Result::UnknownClock`; `Result::ClockSourceFailure`;
 995 |   ///         `Result::ClockOutOfBounds`; `Result::ClockRegression` for a monotonic domain
 996 |   ///         whose reading is below the retained baseline. A rejected read leaves the
 997 |   ///         baseline unchanged.
 998 |   /// \unitspec{T025-U-TIME}
 999 |   [[nodiscard]] Result now(ClockDomainId id, Timestamp &out);
1000 | 
1001 |   /// \brief Maps a source value into a destination domain under a declared rule.
1002 |   /// \param src Declared source domain.
1003 |   /// \param dst Declared destination domain.
1004 |   /// \param value Source-domain value.
1005 |   /// \param out Receives the mapped value only on `Result::Ok`.
1006 |   /// \return `Result::Ok`; `Result::UnknownClock` when `src` is undeclared;
1007 |   ///         `Result::MissingMapping` when no directed `src -> dst` rule exists;
1008 |   ///         `Result::ClockOverflow`; `Result::ClockOutOfBounds`;
1009 |   ///         `Result::ClockSourceFailure`; `Result::ClockRegression`;
1010 |   ///         `Result::ToleranceExceeded` when the mapped value diverges from the
1011 |   ///         destination reading by more than the tolerance.
1012 |   /// \unitspec{T025-U-TIME}
1013 |   [[nodiscard]] Result convert(ClockDomainId src, ClockDomainId dst, Timestamp value,
1014 |                                Timestamp &out);
1015 | 
1016 |   /// \brief Returns the retained regression baseline of a domain.
1017 |   /// \param id Domain token.
1018 |   /// \return The retained regression baseline, or `std::nullopt` when the domain is
1019 |   ///         undeclared or has no successful prior read.
1020 |   /// \unitspec{T025-U-TIME}
1021 |   [[nodiscard]] std::optional<Timestamp> baseline(ClockDomainId id) const;
1022 | 
1023 |   /// \brief Returns the number of declared clock domains.
1024 |   /// \return The number of declared clock domains.
1025 |   /// \unitspec{T025-U-TIME}
1026 |   [[nodiscard]] std::size_t domain_count() const;
1027 | 
1028 |   /// \brief Returns the number of declared mappings.
1029 |   /// \return The number of declared mappings.
1030 |   /// \unitspec{T025-U-TIME}
1031 |   [[nodiscard]] std::size_t mapping_count() const;
1032 | 
1033 | private:
1034 |   /// \brief Grants the session manager access to the non-mutating time-resolution path and to
1035 |   ///        the generation-checked deferred baseline advance, so a successful transition advances
1036 |   ///        the relevant monotonic baselines of the declarations it observed, and a rejected
1037 |   ///        transition — or one whose domain was re-declared in the meantime — changes none of
1038 |   ///        them.
1039 |   /// \unitspec{T025-U-TIME}
1040 |   friend class SessionManager;
1041 | 
1042 |   /// \brief Internal clock-domain entry: identity, semantics, bounds, source, and baseline.
1043 |   /// \unitspec{T025-U-TIME}
1044 |   struct ClockEntry {
1045 |     /// \brief Declared domain token.
1046 |     /// \unitspec{T025-U-TIME}
1047 |     ClockDomainId id{kInvalidClockDomain};
1048 |     /// \brief Monotonic or wall-clock semantics.
1049 |     /// \unitspec{T025-U-TIME}
